<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { api, rows, keyOf, pretty, type Row } from './api'
import JsonView from './JsonView.vue'
defineProps<{ admin: boolean }>()
const kbs = ref<Row[]>([]), docs = ref<Row[]>([]), kbId = ref(''), trash = ref(false), error = ref(''), busy = ref(false), detail = ref<any>(null), dialog = ref(false)
const acl = ref(''), aclTarget = ref(''), aclOpen = ref(false), files = ref<File[]>([]), nextCursor = ref(''), searchQuery = ref(''), buildConfig = ref('{"embedding": true}'), importPath = ref(''), importPreview = ref<any>(null)
async function act(fn: () => Promise<void>) { error.value = ''; busy.value = true; try { await fn() } catch (e) { error.value = String(e) } finally { busy.value = false } }
async function load(append = false) { const path = trash.value ? '/admin/documents?status=TRASHED' : '/documents?kbId=' + encodeURIComponent(kbId.value); const result = await api(path + (append && nextCursor.value ? '&cursor=' + encodeURIComponent(nextCursor.value) : '')); docs.value = append ? [...docs.value, ...rows(result)] : rows(result); nextCursor.value = result.nextCursor || '' }
onMounted(() => act(async () => { kbs.value = rows(await api('/knowledge-bases')); kbId.value = keyOf(kbs.value[0] || {}) || ''; await load() }))
async function upload() { await act(async () => { if (!kbId.value || !files.value.length) throw new Error('请选择知识库和文件'); for (const file of files.value) { const form = new FormData(); form.append('file', file); form.append('buildConfig', JSON.stringify(JSON.parse(buildConfig.value))); form.append('kbId', kbId.value); const target = file.name.toLowerCase().endsWith('.zip') ? '/admin/wiki-imports' : '/admin/documents'; detail.value = await api(target, 'POST', form) } dialog.value = true; files.value = []; await load() }) }
async function inspect(row: Row) { await act(async () => { const document = await api('/documents/' + keyOf(row)); const version = document.activeVersionId || document.versionId || document.activeVersion?.id || row.activeVersionId; detail.value = version ? await api(`/documents/${keyOf(row)}/versions/${version}/preview`) : document; dialog.value = true }) }
async function lifecycle(row: Row, action: string) { if (action === 'purge') { try { await ElMessageBox.confirm('永久清除会删除原件和派生内容，无法恢复。确认清除该资料？', '永久清除', { type: 'warning', confirmButtonText: '永久清除', cancelButtonText: '取消' }) } catch { return } } await act(async () => { detail.value = await api(`/admin/documents/${keyOf(row)}/${action}`, 'POST', { expectedVersion: row.version ?? row.rowVersion ?? row.lifecycleVersion }); await load() }) }
async function editAcl(target: string) { await act(async () => { aclTarget.value = target; const value = await api(target); acl.value = pretty({ ...value, expectedVersion: value.rowVersion ?? value.expectedVersion }); aclOpen.value = true }) }
async function saveAcl() { await act(async () => { await api(aclTarget.value, 'PUT', JSON.parse(acl.value)); aclOpen.value = false; await load() }) }
async function createKb() { try { const { value } = await ElMessageBox.prompt('请输入知识库名称；默认仅向当前用户开放，后续可编辑授权。', '新建知识库', { inputValidator: value => !!value?.trim() || '名称不能为空' }); await act(async () => { const me = await api('/me'); await api('/admin/knowledge-bases', 'POST', { name: value, readers: [{ type: 'USER', userId: me.id || me.userId }] }); kbs.value = rows(await api('/knowledge-bases')) }) } catch { /* dialog cancelled */ } }
async function newVersion(row: Row, event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; await act(async () => { const form = new FormData(); form.append('file', file); form.append('buildConfig', JSON.stringify(JSON.parse(buildConfig.value))); detail.value = await api(`/admin/documents/${keyOf(row)}/versions`, 'POST', form); dialog.value = true; await load() }) }
async function previewDirectory() { await act(async () => { if (!importPath.value.trim()) throw new Error('请输入导入目录'); importPreview.value = await api('/admin/import-previews', 'POST', { rootAlias: 'default', relativePath: importPath.value.trim() }); detail.value = importPreview.value; dialog.value = true }) }
async function importDirectory() { await act(async () => { if (!kbId.value || !importPreview.value?.estimateId) throw new Error('请先选择知识库并预览目录'); const selected = rows(importPreview.value.files || importPreview.value).map((row: Row) => row.relativePath).filter(Boolean); detail.value = await api('/admin/imports', 'POST', { estimateId: importPreview.value.estimateId, kbId: kbId.value, files: selected }); importPreview.value = null; dialog.value = true; await load() }) }
async function acceptWarnings() { if (!detail.value?.buildId) return; try { const { value } = await ElMessageBox.prompt('请输入人工放行原因。', '接受解析告警', { inputValidator: value => !!value?.trim() || '原因不能为空' }); await act(async () => { detail.value = await api('/admin/builds/' + detail.value.buildId + '/accept-warnings', 'POST', { reason: value }); await load() }) } catch { /* dialog cancelled */ } }
</script>
<template><section><h2>资料与授权</h2><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="toolbar"><el-select v-model="kbId" placeholder="知识库" @change="act(() => load())"><el-option v-for="kb in kbs" :key="keyOf(kb)" :label="kb.name" :value="keyOf(kb)" /></el-select><el-switch v-if="admin" v-model="trash" active-text="回收站" @change="act(() => load())" /><el-button :loading="busy" @click="act(() => load())">刷新</el-button><template v-if="admin"><el-button @click="createKb">新建知识库</el-button><el-button :disabled="!kbId" @click="editAcl('/admin/knowledge-bases/' + kbId + '/acl')">知识库授权</el-button></template></div><div v-if="admin && !trash" class="toolbar"><input class="file" type="file" multiple accept=".md,.txt,.pdf,.docx,.html,.zip" aria-label="选择上传资料" @change="files = Array.from(($event.target as HTMLInputElement).files || [])"><el-button type="primary" :loading="busy" :disabled="!files.length" @click="upload">上传 {{ files.length || '' }}</el-button><span class="muted">ZIP 按 Wiki 包导入；发布前由后台解析与质量检查，新版失败不会替换旧版。</span></div><div v-if="admin && !trash" class="toolbar"><el-input v-model="importPath" placeholder="服务器导入目录（相对 RAG_IMPORT_ROOT）" /><el-button :disabled="!importPath.trim()" @click="previewDirectory">预览目录</el-button><el-button :disabled="!importPreview?.estimateId" @click="importDirectory">导入预览文件</el-button></div><el-collapse v-if="admin"><el-collapse-item title="本次构建选项"><p class="muted">默认仅原文 BM25；开启 embedding、summary、questions 或 vision 需要相应模型与预算。</p><el-input v-model="buildConfig" type="textarea" :rows="3" aria-label="构建配置 JSON" /></el-collapse-item></el-collapse><div v-if="!trash" class="toolbar"><el-input v-model="searchQuery" placeholder="在当前知识库检索原文" maxlength="2000" /><el-button :disabled="!searchQuery.trim()" @click="act(async () => { detail = await api('/search?query=' + encodeURIComponent(searchQuery) + (kbId ? '&kbIds=' + encodeURIComponent(kbId) : '')); dialog = true })">BM25 搜索</el-button></div><el-table :data="docs" v-loading="busy" empty-text="没有当前可见的资料"><el-table-column label="资料" min-width="180"><template #default="{ row }">{{ row.title || row.name || row.filename || keyOf(row) }}</template></el-table-column><el-table-column prop="status" label="状态" width="130" /><el-table-column label="版本" width="100"><template #default="{ row }">{{ row.versionNo || row.activeVersion?.versionNo || '—' }}</template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{ row }"><el-button size="small" @click="inspect(row)">解析预览</el-button><template v-if="admin"><el-button size="small" @click="editAcl('/admin/documents/' + keyOf(row) + '/acl')">权限</el-button><template v-if="!trash"><label class="el-button el-button--small">新版本<input type="file" hidden @change="newVersion(row, $event)"></label><el-button size="small" @click="lifecycle(row, 'trash')">移入回收站</el-button></template><template v-else><el-button size="small" @click="lifecycle(row, 'restore')">恢复</el-button><el-button size="small" type="danger" @click="lifecycle(row, 'purge')">永久清除</el-button></template></template></template></el-table-column></el-table><el-button v-if="nextCursor" @click="act(() => load(true))">加载下一页</el-button><el-dialog v-model="dialog" title="解析预览 / 任务结果" width="850px"><JsonView :value="detail" /><template #footer><el-button v-if="admin && detail?.status === 'NEEDS_REVIEW' && detail?.buildId" type="warning" @click="acceptWarnings">接受告警并继续构建</el-button></template></el-dialog><el-dialog v-model="aclOpen" title="授权（保留服务端返回的版本号）" width="700px"><p>读者 type 为 ALL、GROUP 或 USER；组和用户使用真实 ID。文档 mode 为 INHERIT 或 RESTRICT。</p><el-input v-model="acl" type="textarea" :rows="14" aria-label="ACL JSON" /><template #footer><el-button :loading="busy" type="primary" @click="saveAcl">保存授权</el-button></template></el-dialog></section></template>
